CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, password_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT pk_users PRIMARY KEY (id), CONSTRAINT uk_users_email UNIQUE (email));
CREATE TABLE tasks (id BIGINT NOT NULL AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, description VARCHAR(2000) NULL, due_date DATE NULL, priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', status VARCHAR(20) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), CONSTRAINT pk_tasks PRIMARY KEY (id), CONSTRAINT fk_tasks_owner FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT chk_tasks_priority CHECK (priority IN ('LOW','MEDIUM','HIGH')), CONSTRAINT chk_tasks_status CHECK (status IN ('PENDING','IN_PROGRESS','COMPLETED')));
CREATE INDEX idx_tasks_owner_status ON tasks(owner_id,status);
CREATE INDEX idx_tasks_owner_due ON tasks(owner_id,due_date);